let data = msg.payload;
try {
    if (typeof data === 'string') {
        data = JSON.parse(data);
    }
} catch (e) {
    node.error('JSON parse error: ' + e.message, msg);
    return null;
}

if (data && (data.asset_id === 'asset_3' || (msg.topic && msg.topic.includes('asset_3')))) {
    msg.payload = data;
    const part = data.part_number ? (' | Part: ' + data.part_number) : '';
    node.status({ fill: 'green', shape: 'dot', text: 'Asset 3: ' + data.temperature + '°C | ' + data.motor_speed + ' RPM' + part });
    return msg;
}

return null;
